43	/// Validate one completions request and proxy it into the shared `vllm-text`
44	/// stack.
45	pub async fn completions(
46	    State(state): State<Arc<AppState>>,
47	    headers: HeaderMap,
48	    ValidatedJson(body): ValidatedJson<CompletionRequest>,
49	) -> Response {
50	    let stream = body.stream;
51	    let request_context = resolve_request_context(&headers, body.request_id.as_deref());
52	    let lora_resolution = state.resolve_model_with_loras(Some(&body.model)).await;
53	
54	    let prepared = match prepare_completion_request(body, &lora_resolution, request_context) {
55	        Ok(prepared) => prepared,
56	        Err(error) => return error.into_response(),
57	    };
58	    let request_span = tracing::info_span!(
59	        "completions",
60	        request_id = %prepared.request_id,
61	        engine_request_id = tracing::field::Empty,
62	    );
63	
64	    let created = unix_timestamp();
65	    let api_server_options = state.api_server_options;
66	    let text_stream = match state
67	        .chat
68	        .text()
69	        .generate(prepared.text_request)
70	        .instrument(request_span.clone())
71	        .await
72	    {
73	        Ok(stream) => stream,
74	        Err(error) => {
75	            return text_submit_error("failed to submit completion request", error).into_response();
76	        }
77	    };
78	
79	    if stream {
80	        let chunk_stream = completion_chunk_stream(
81	            text_stream,
82	            prepared.request_id,
83	            prepared.response_model,
84	            created,
85	            api_server_options,
86	            prepared.options,
87	        );
88	        let sse_stream = completion_sse_stream(chunk_stream).instrument(request_span);
89	
90	        Sse::new(sse_stream).into_response()
91	    } else {
92	        let response = match collect_completion(
93	            text_stream,
94	            prepared.request_id,
95	            prepared.response_model,
96	            created,
97	            api_server_options,
98	            prepared.options,
99	        )
100	        .instrument(request_span.clone())
101	        .await
102	        {
103	            Ok(response) => response,
104	            Err(error) => return error.into_response(),
105	        };
106	
107	        Json(response).into_response()
108	    }
109	}
